import { field, select, textarea, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "taAttr", label: "HTML attribute name", value: "data-size" })}${select({ id: "taType", label: "Type", options: [{label:"string",value:"string"},{label:"number",value:"number"},{label:"px",value:"px"},{label:"em",value:"em"},{label:"rem",value:"rem"},{label:"color",value:"color"},{label:"deg",value:"deg"},{label:"%",value:"percent"},{label:"s",value:"s"},{label:"ms",value:"ms"},{label:"url",value:"url"}], value: "px" })}</div><div class="field-grid">${field({ id: "taFallback", label: "Fallback value", value: "16px" })}${field({ id: "taProperty", label: "CSS property", value: "font-size" })}</div><div class="field-grid">${field({ id: "taSelector", label: "Selector", value: "[data-size]" })}${field({ id: "taSample", label: "Sample attribute value (preview)", value: "24px" })}</div><div class="field-grid">${textarea({ id: "taHtml", label: "Sample HTML (for output)", value: '<div data-size="24px">Sized text</div>\n<span data-size="18px">Smaller text</span>' })}</div>`,generate(root) {const attr = root.querySelector("#taAttr").value.trim() || "data-size";const type = root.querySelector("#taType").value;const fallback = root.querySelector("#taFallback").value.trim() || "16px";const property = root.querySelector("#taProperty").value.trim() || "font-size";const selector = root.querySelector("#taSelector").value.trim() || `[${attr}]`;const sampleVal = root.querySelector("#taSample").value.trim() || "24px";const htmlSample = root.querySelector("#taHtml").value.trim();const typeMap = { percent: "%", s: "s", ms: "ms", url: "url" };const typeStr = typeMap[type] || type;const lines = [];lines.push("/* Typed attr() — Chrome 133+ */");lines.push("/* Casts an HTML attribute value to a typed CSS value with fallback. */");lines.push("");lines.push(`/* Typed attr() declaration */`);lines.push(`${selector} {`);lines.push(` ${property}: attr(${attr} type(${typeStr}), ${fallback});`);lines.push(`}`);lines.push("");lines.push("/* Standard attr() fallback for older browsers */");lines.push(`${selector} {`);lines.push(` ${property}: ${fallback}; /* fallback */`);lines.push(` ${property}: attr(${attr} type(${typeStr}), ${fallback});`);lines.push(`}`);lines.push("");lines.push("/* Browser support: Chrome 133+, Edge 133+. Firefox and Safari in development. */");lines.push("/* Without typed attr(), only the `string` type works, and only on ::before/::after content. */");lines.push("/* Typed attr() enables using attribute values in any CSS property with proper type coercion. */");if (htmlSample) {lines.push("");lines.push("/* Sample HTML */");lines.push(htmlSample);}const previewProp = property;const previewVal = sampleVal || fallback;const preview = `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:16px;background:#f9fafb"><div style="font-size:12px;font-weight:600;margin-bottom:10px;color:#374151">Preview: <code style="background:#f3f4f6;padding:1px 4px;border-radius:3px">${attr}="${previewVal}"</code> → <code style="background:#f3f4f6;padding:1px 4px;border-radius:3px">${property}: ${previewVal}</code></div><div style="background:#fff;border:1px dashed #d1d5db;border-radius:6px;padding:20px;text-align:center"><div style="${previewProp}:${previewVal};display:inline-block">${attr}: "${previewVal}"</div></div><div style="font-size:11px;color:#6b7280;margin-top:8px">Type: <strong>${typeStr}</strong> | Fallback: <strong>${fallback}</strong> | The rendered element above uses the CSS property with the sample value applied.</div></div>`;return { output: lines.join("\n"), preview };}};